// --- THEME & COLORS ---
private val DarkColorScheme = darkColorScheme(
 primary = Color(0xFFFF7A00), // SafetyOrange
 background = Color(0xFF1A1C2C), // MidnightBlue
 surface = Color(0xFF2A2D40), // DarkSurface
 onPrimary = Color.White,
 onBackground = Color.White,
 onSurface = Color.White,
 onSurfaceVariant = Color(0xFF9E9E9E), // MutedGray
 error = Color(0xFFD32F2F) // A brighter red for the call button
)

// --- DATA MODELS & VIEWMODEL ---
data class WeatherResponse(val main: Main, val weather: List<Weather>, val name: String)
data class Main(val temp: Double)
data class Weather(val main: String, val icon: String)

data class LatLng(val lat: Double, val lon: Double)

sealed interface WeatherState {
 data object Loading : WeatherState
 data class Success(
 val location: String,
 val temperature: String,
 val condition: String,
 val iconUrl: String,
 val lat: Double,
 val lon: Double
 ) : WeatherState
 data class Error(val message: String) : WeatherState
}

class WeatherViewModel(application: Application) : AndroidViewModel(application) {
 private val _weatherState = MutableStateFlow<WeatherState>(WeatherState.Loading)
 val weatherState: StateFlow<WeatherState> = _weatherState
 private val apiKey = "de9f8eb51584955d6d6fe607c9d81c84"

 @Suppress("DEPRECATION")
 fun fetchWeatherByLocation(lat: Double, lon: Double) {
 viewModelScope.launch {
 if (weatherState.value !is WeatherState.Success) _weatherState.value = WeatherState.Loading
 try {
 val weatherResponse = RetrofitClient.instance.getCurrentWeatherByLocation(lat, lon, apiKey)

 val locationName = try {
 val geocoder = Geocoder(getApplication(), Locale.getDefault())
 geocoder.getFromLocation(lat, lon, 1)?.firstOrNull()?.locality ?: weatherResponse.name
 } catch (_: Exception) {
 weatherResponse.name // Fallback to API name if Geocoder fails
 }

 val iconCode = weatherResponse.weather.firstOrNull()?.icon ?: "01d"

 _weatherState.value = WeatherState.Success(
 location = "$locationName, PH",
 temperature = "${String.format(Locale.US, "%.1f", weatherResponse.main.temp)}°C",
 condition = weatherResponse.weather.firstOrNull()?.main ?: "Clear",
 iconUrl = "https://openweathermap.org/img/wn/$iconCode@4x.png",
 lat = lat,
 lon = lon
 )
 } catch (_: Exception) {
 _weatherState.value = WeatherState.Error("Failed to load weather. Check connection.")
 }
 }
 }
 fun setLocationPermissionDenied() { _weatherState.value = WeatherState.Error("Permission denied. Enable location in settings.") }
 fun setLocationNotFound() { _weatherState.value = WeatherState.Error("GPS signal lost. Ensure location is on.") }
}

interface WeatherApiService {
 @GET("data/2.5/weather")
 suspend fun getCurrentWeatherByLocation(@Query("lat") lat: Double, @Query("lon") lon: Double, @Query("appid") apiKey: String, @Query("units") units: String = "metric"): WeatherResponse
}
object RetrofitClient {
 private const val BASE_URL = "https://api.openweathermap.org/"
 val instance: WeatherApiService by lazy {
 Retrofit.Builder().baseUrl(BASE_URL).addConverterFactory(GsonConverterFactory.create()).build().create(WeatherApiService::class.java)
 }
}


// --- MAIN ACTIVITY & APP CONTAINER ---
class MainActivity : ComponentActivity() {
 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 MaterialTheme(colorScheme = DarkColorScheme) { 
 EmergencyApp()
 }
 }
 }
}

@Composable
fun EmergencyApp() {
 var selectedScreen by remember { mutableIntStateOf(0) }
 var showEmergencyContacts by remember { mutableStateOf(false) }
 var showReportIncident by remember { mutableStateOf(false) }
 val weatherViewModel: WeatherViewModel = viewModel()

 when {
 showEmergencyContacts -> EmergencyContactsScreen(onBackPressed = { showEmergencyContacts = false })
 showReportIncident -> ReportIncidentScreen(weatherState = weatherViewModel.weatherState.collectAsState().value, onBackPressed = { showReportIncident = false })
 else -> {
 Scaffold(
 containerColor = MaterialTheme.colorScheme.background,
 bottomBar = { AppBottomNavigation(selectedScreen = selectedScreen, onScreenSelected = { selectedScreen = it }) }
 ) { innerPadding ->
 Box(modifier = Modifier.padding(innerPadding)) {
 when (selectedScreen) {
 0 -> HomeScreen(onEmergencyCallClick = { showEmergencyContacts = true }, onReportIncidentClick = { showReportIncident = true }, weatherViewModel = weatherViewModel)
 1 -> AlertsScreen()
 2 -> ProfileScreen()
 }
 }
 }
 }
 }
}

// --- SCREENS ---
@Composable
fun HomeScreen(
 onEmergencyCallClick: () -> Unit,
 onReportIncidentClick: () -> Unit,
 weatherViewModel: WeatherViewModel
) {
 val context = LocalContext.current
 val fusedLocationClient = remember { LocationServices.getFusedLocationProviderClient(context) }

 val locationPermissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { permissions ->
 if (permissions.getOrDefault(Manifest.permission.ACCESS_FINE_LOCATION, false) || permissions.getOrDefault(Manifest.permission.ACCESS_COARSE_LOCATION, false)) {
 if (ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED || ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED) {
 try {
 val cts = CancellationTokenSource()
 fusedLocationClient.getCurrentLocation(Priority.PRIORITY_HIGH_ACCURACY, cts.token)
 .addOnSuccessListener { location ->
 if (location != null) weatherViewModel.fetchWeatherByLocation(location.latitude, location.longitude)
 else weatherViewModel.setLocationNotFound()
 }
 } catch (_: SecurityException) {
 weatherViewModel.setLocationPermissionDenied()
 }
 }
 } else {
 weatherViewModel.setLocationPermissionDenied()
 }
 }

 LaunchedEffect(Unit) {
 locationPermissionLauncher.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION))
 }

 LazyColumn(
 modifier = Modifier.fillMaxSize().padding(horizontal = 16.dp),
 verticalArrangement = Arrangement.spacedBy(20.dp)
 ) {
 item {
 Spacer(modifier = Modifier.height(16.dp))
 Text("Emergency Dashboard", fontSize = 28.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground)
 Text("Built by Students, for the Community", fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
 Spacer(modifier = Modifier.height(24.dp))
 }
 item { ActionGrid(onEmergencyCallClick, onReportClick = onReportIncidentClick, onSafeClick = {}) }
 item { WeatherWidget(weatherViewModel.weatherState.collectAsState().value) }
 }
}

@Composable
fun ReportIncidentScreen(
