 var selectedUrgency by remember { mutableStateOf(urgencyLevels.first()) }

 // --- User location from weatherState ---
 val userLocation: LatLng? = if (weatherState is WeatherState.Success) {
 LatLng(weatherState.lat, weatherState.lon)
 } else null

 Scaffold(containerColor = MaterialTheme.colorScheme.background) { paddingValues ->
 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues)
 .padding(16.dp),
 verticalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 // --- Header ---
 item {
 Text(
 "Report an Incident",
 fontSize = 24.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onBackground
 )
 Text(
 "Your current location will be attached automatically.",
 fontSize = 14.sp,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 }

 // --- Map ---
 item {
 RealTimeLocationMap(userLocation = userLocation)
 }

 // --- Incident Type ---
 item {
 SectionTitle("Type of Incident")
 SegmentedButtonRow(incidentTypes, selectedIncidentType) { selectedIncidentType = it }
 }

 // --- Urgency Level ---
 item {
 SectionTitle("Urgency Level")
 SegmentedButtonRow(urgencyLevels, selectedUrgency) { selectedUrgency = it }
 }

 // --- Reporter Name ---
 item {
 SectionTitle("Your Name (Optional)")
 OutlinedTextField(
 value = reporterName,
 onValueChange = { reporterName = it },
 label = { Text("Defaults to Anonymous") },
 modifier = Modifier.fillMaxWidth(),
 colors = OutlinedTextFieldDefaults.colors(
 focusedBorderColor = MaterialTheme.colorScheme.primary,
 unfocusedBorderColor = MaterialTheme.colorScheme.onSurfaceVariant,
 focusedLabelColor = MaterialTheme.colorScheme.primary,
 unfocusedLabelColor = MaterialTheme.colorScheme.onSurfaceVariant,
 cursorColor = MaterialTheme.colorScheme.primary
 )
 )
 }

 // --- Incident Details ---
 item {
 SectionTitle("Details of Incident")
 OutlinedTextField(
 value = incidentDetails,
 onValueChange = { incidentDetails = it },
 label = { Text("Provide as much detail as possible...") },
 modifier = Modifier
 .fillMaxWidth()
 .height(120.dp),
 colors = OutlinedTextFieldDefaults.colors(
 focusedBorderColor = MaterialTheme.colorScheme.primary,
 unfocusedBorderColor = MaterialTheme.colorScheme.onSurfaceVariant,
 focusedLabelColor = MaterialTheme.colorScheme.primary,
 unfocusedLabelColor = MaterialTheme.colorScheme.onSurfaceVariant,
 cursorColor = MaterialTheme.colorScheme.primary
 )
 )
 }

 // --- Attach Photo Button ---
 item {
 OutlinedButton(
 onClick = { /* TODO: Attach photo */ },
 modifier = Modifier.fillMaxWidth()
 ) {
 Text("Attach Photo", color = MaterialTheme.colorScheme.primary)
 }
 }

 // --- Action Buttons ---
 item {
 Spacer(modifier = Modifier.height(16.dp))
 Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
 Button(
 onClick = onBackPressed,
 modifier = Modifier.weight(1f),
 colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.surface)
 ) {
 Text("Cancel")
 }
 Button(
 onClick = { /* TODO: Submit report */ },
 modifier = Modifier.weight(1f),
 colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary)
 ) {
 Text("Submit Report")
 }
 }
 }
 }
 }
}


@SuppressLint("SetJavaScriptEnabled")
@Composable
fun RealTimeLocationMap(userLocation: LatLng?) {
 val context = LocalContext.current
 var location by remember { mutableStateOf(userLocation ?: LatLng(14.5995, 120.9842)) } // Default Manila
 var showDot by remember { mutableStateOf(true) }

 // Blinking effect
 LaunchedEffect(Unit) {
 while (true) {
 showDot = !showDot
 kotlinx.coroutines.delay(500) // blink every 0.5s
 }
 }

 // Update location whenever userLocation changes
 LaunchedEffect(userLocation) {
 userLocation?.let { location = it }
 }

 // Construct OpenStreetMap static URL
 val mapUrl = "https://staticmap.openstreetmap.de/staticmap.php?center=${location.lat},${location.lon}&zoom=16&size=600x400"

 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(300.dp)
 .clip(RoundedCornerShape(16.dp))
 ) {
 // Map Image
 AsyncImage(
 model = mapUrl,
 contentDescription = "User Location Map",
 modifier = Modifier.fillMaxSize()
 )

 // Blinking red dot
 if (showDot) {
 Box(
 modifier = Modifier
 .size(16.dp)
 .background(Color.Red, shape = CircleShape)
 .align(Alignment.Center) // approximate center
 )
 }
 }
}



